import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { normalizeId } from '../src/customers.js';

test('createInvoice returns a draft invoice with complete line details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2023-10-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice supports multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Copywriting (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2023-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice reports DATE_INVALID for non-YYYY-MM-DD format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/15/2023',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for invalid format variations', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-1-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES for missing lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for zero qty', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for negative qty', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for unknown product', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-10-15',
      lines: [{ sku: 'INVALID-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice returns a copy of the result', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  r1.value.customerId = 'C-999';
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.value.customerId, 'C-001');
});

test('createInvoice validates customer first', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: 'invalid',
      lines: [],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1000 }), 1000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('invoiceTotals calculates subtotal for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  // C-001 is gold tier, gets 5% discount
  // Subtotal: 5 * 8500 = 42500
  // Discount: 42500 * 5 / 100 = 2125
  // After discount: 40375
  // VAT (21%): 40375 * 21 / 100 = 8478.75, rounded = 8479
  // Total: 40375 + 8479 = 48854
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals calculates subtotal for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // C-001 is gold tier, gets 5% discount on each line
  // DES-HOUR: 5 * 8500 = 42500, discount: 2125, after discount: 40375, VAT: 8479
  // COPY-HOUR: 2 * 6000 = 12000, discount: 600, after discount: 11400, VAT: 2394
  // Subtotal: 54500, Total discount: 2725, Total VAT: 10873, Total: 62648
  assert.equal(totals.subtotal, 54500);
  assert.equal(totals.discount, 2725);
  assert.equal(totals.vat, 10873);
  assert.equal(totals.total, 62648);
});

test('invoiceTotals calculates correctly with many lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // C-001 is gold tier, gets 5% discount on each line
  // DES-HOUR: 10 * 8500 = 85000, discount: 4250, after: 80750, VAT: 16957.5 -> 16958
  // DEV-HOUR: 8 * 9500 = 76000, discount: 3800, after: 72200, VAT: 15162
  // ICON-SET: 3 * 980 = 2940, discount: 147, after: 2793, VAT: 586.53 -> 587
  // Subtotal: 163940, Total discount: 8197, Total VAT: 32707, Total: 188450
  assert.equal(totals.subtotal, 163940);
  assert.equal(totals.discount, 8197);
  assert.equal(totals.vat, 32707);
  assert.equal(totals.total, 188450);
});

test('invoiceTotals returns a copy', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals1 = invoiceTotals(r.value);
  totals1.subtotal = 99999;
  const totals2 = invoiceTotals(r.value);
  assert.equal(totals2.subtotal, 42500);
});

test('addLine adds a new line to the invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'COPY-HOUR');
  assert.equal(r2.value.lines[1].qty, 2);
  assert.equal(r2.value.lines[1].name, 'Copywriting (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('addLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'finalized',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(
    addLine(invoice, { sku: 'COPY-HOUR', qty: 1 }),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('addLine returns QTY_INVALID for invalid qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    addLine(r.value, { sku: 'COPY-HOUR', qty: 1.5 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('addLine returns QTY_INVALID for zero qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    addLine(r.value, { sku: 'COPY-HOUR', qty: 0 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('addLine returns UNKNOWN_SKU for invalid product', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    addLine(r.value, { sku: 'INVALID-SKU', qty: 1 }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r.value;
  addLine(original, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(original.lines.length, 1);
  assert.equal(original.lines[0].sku, 'DES-HOUR');
});

test('removeLine removes a line from the invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'COPY-HOUR');
});

test('removeLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'finalized',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'COPY-HOUR', qty: 2, name: 'Copywriting (hour)', unitPrice: 6000, vatRate: 21 },
    ],
  };
  assert.deepEqual(
    removeLine(invoice, 'DES-HOUR'),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    removeLine(r.value, 'COPY-HOUR'),
    { ok: false, error: 'LINE_NOT_FOUND' }
  );
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(
    removeLine(r.value, 'DES-HOUR'),
    { ok: false, error: 'NO_LINES' }
  );
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const original = r.value;
  removeLine(original, 'COPY-HOUR');
  assert.equal(original.lines.length, 2);
  assert.equal(original.lines[1].sku, 'COPY-HOUR');
});

test('addLine and removeLine work together', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r.value, { sku: 'COPY-HOUR', qty: 2 });
  const r3 = addLine(r2.value, { sku: 'ICON-SET', qty: 3 });
  const r4 = removeLine(r3.value, 'COPY-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.equal(r4.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r4.value.lines[1].sku, 'ICON-SET');
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.number, 'INV-2023-0001');
});

test('issueInvoice assigns the next available number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existing = ['INV-2023-0001', 'INV-2023-0002'];
  const r2 = issueInvoice(r.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2023-0003');
});

test('issueInvoice uses year from issue date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existing = ['INV-2023-0001'];
  const r2 = issueInvoice(r.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2024-0001');
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2023-10-15',
    status: 'issued',
    number: 'INV-2023-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(
    issueInvoice(invoice, []),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('issueInvoice preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2023-10-15');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].qty, 5);
  assert.equal(r2.value.lines[1].qty, 2);
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r.value;
  issueInvoice(original, []);
  assert.equal(original.status, 'draft');
  assert.ok(!original.number);
});

test('createInvoice accepts discountPercent on a line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
