  });
  const result = applyVoucher(r.value, { code: 'SAVE10', amount: 1000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 1000);
});

test('applyVoucher error: NOT_DRAFT on issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = { ...r.value, status: 'issued', number: 'INV-2023-0001' };
  const result = applyVoucher(issued, { code: 'SAVE10', amount: 1000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('applyVoucher error: VOUCHER_EXISTS when already has voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const withVoucher = {
    ...r.value,
    voucher: { code: 'OLD10', amount: 500 },
  };
  const result = applyVoucher(withVoucher, { code: 'NEW10', amount: 1000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'VOUCHER_EXISTS');
});

test('applyVoucher error: AMOUNT_INVALID for non-integer', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = applyVoucher(r.value, { code: 'SAVE10', amount: 1000.5 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('applyVoucher error: AMOUNT_INVALID for zero', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = applyVoucher(r.value, { code: 'SAVE10', amount: 0 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

